INSERT INTO games (slug, title, short_description, about, developer, publisher, release_date, genres, tags, features, hero_image, box_image, rating, price_display, featured) VALUES
('elden-ring', 'Elden Ring', 'A vast fantasy world of wonder and peril awaits in FromSoftware''s biggest adventure yet.', 'Rise, Tarnished, and be guided by grace to brandish the power of the Elden Ring. Explore the Lands Between, a breathtaking world filled with peril and wonder, and face demigods to become an Elden Lord. With deep, challenging combat and a vast open world co-created with George R. R. Martin, Elden Ring is a landmark action RPG.', 'FromSoftware', 'Bandai Namco Entertainment', '2022-02-25', ARRAY['Action','RPG','Adventure'], ARRAY['Open World','Souls-like','Difficult','Dark Fantasy','Story Rich'], ARRAY['Single-player','Online Co-op','Online PvP','Controller Support','Achievements'], 'https://upload.wikimedia.org/wikipedia/en/3/36/Elden_Ring_The_Ring_of_Digital_version.jpg', 'https://upload.wikimedia.org/wikipedia/en/3/36/Elden_Ring_The_Ring_of_Digital_version.jpg', 96, '$59.99', true),
('the-legend-of-zelda-tears-of-the-kingdom', 'The Legend of Zelda: Tears of the Kingdom', 'An epic adventure across the land and skies of Hyrule.', 'In the sequel to Breath of the Wild, Link explores the sprawling skies and deep depths of Hyrule. With new abilities like Ultrahand and Fuse, you can craft weapons, build vehicles, and solve puzzles in a world that rewards creativity like no other.', 'Nintendo EPD', 'Nintendo', '2023-05-12', ARRAY['Action','Adventure','RPG'], ARRAY['Open World','Crafting','Puzzle','Story Rich','Exploration'], ARRAY['Single-player','Controller Support'], 'https://upload.wikimedia.org/wikipedia/en/3/3d/The_Legend_of_Zelda_Tears_of_the_Kingdom_box_art.jpg', 'https://upload.wikimedia.org/wikipedia/en/3/3d/The_Legend_of_Zelda_Tears_of_the_Kingdom_box_art.jpg', 96, '$69.99', true),
('baldur-s-gate-3', 'Baldur''s Gate 3', 'Gather your party and return to the Forgotten Realms in this epic RPG.', 'An epic narrative RPG set in the world of Dungeons & Dragons. Forge your destiny through hundreds of choices, turn-based tactical combat, and a sprawling story of up to 4-player co-op. Baldur''s Gate 3 redefines what a CRPG can be, with unforgettable characters and truly reactive storytelling.', 'Larian Studios', 'Larian Studios', '2023-08-03', ARRAY['RPG','Strategy','Adventure'], ARRAY['Turn-Based','Story Rich','Co-op','Character Customization','Choices Matter'], ARRAY['Single-player','Online Co-op','Local Co-op','Controller Support','Cloud Saves','Achievements'], 'https://upload.wikimedia.org/wikipedia/en/1/12/Baldur%27s_Gate_3_cover_art.jpg', 'https://upload.wikimedia.org/wikipedia/en/1/12/Baldur%27s_Gate_3_cover_art.jpg', 96, '$59.99', true),
('red-dead-redemption-2', 'Red Dead Redemption 2', 'America, 1899. The end of the Wild West era is near.', 'Arthur Morgan and the Van der Linde gang are on the run. This sprawling epic of life in America''s unforgiving heartland features a massive open world, deep characters, and a story of loyalty and betrayal. Every detail of this living world is crafted to draw you into the dying days of the outlaw era.', 'Rockstar Games', 'Rockstar Games', '2018-10-26', ARRAY['Action','Adventure'], ARRAY['Open World','Western','Story Rich','Third-Person','Atmospheric'], ARRAY['Single-player','Online PvP','Controller Support','Achievements'], 'https://upload.wikimedia.org/wikipedia/en/4/4c/Red_Dead_Redemption_2.jpg', 'https://upload.wikimedia.org/wikipedia/en/4/4c/Red_Dead_Redemption_2.jpg', 97, '$59.99', true),
('cyberpunk-2077', 'Cyberpunk 2077', 'An open-world action-adventure story set in Night City.', 'Become a cyberpunk mercenary in the megalopolis of Night City, where style and violence meet in a dystopian future. With the heart-pounding story of the Phantom Liberty expansion and the vibrant open world, Cyberpunk 2077 is a thrilling RPG of ambition, body modification, and neon-lit danger.', 'CD Projekt Red', 'CD Projekt', '2020-12-10', ARRAY['RPG','Action','Shooter'], ARRAY['Open World','Cyberpunk','Story Rich','First-Person','Sci-fi'], ARRAY['Single-player','Controller Support','Achievements','Cloud Saves'], 'https://upload.wikimedia.org/wikipedia/en/9/9f/Cyberpunk_2077_box_art.jpg', 'https://upload.wikimedia.org/wikipedia/en/9/9f/Cyberpunk_2077_box_art.jpg', 86, '$59.99', true),
('stardew-valley', 'Stardew Valley', 'A beloved farming sim where you build the life of your dreams.', 'You''ve inherited your grandfather''s old farm plot in Stardew Valley. Armed with hand-me-down tools, set out to build a new life. Grow crops, raise animals, mine for treasure, befriend townsfolk, and maybe find love in this charming, endlessly relaxing farming adventure with surprising depth.', 'ConcernedApe', 'ConcernedApe', '2016-02-26', ARRAY['Simulation','RPG','Indie'], ARRAY['Farming Sim','Cozy','Crafting','Pixel Graphics','Relaxing'], ARRAY['Single-player','Online Co-op','Local Co-op','Controller Support','Cloud Saves','Achievements'], 'https://upload.wikimedia.org/wikipedia/en/1/11/Stardew_Valley_cover.jpg', 'https://upload.wikimedia.org/wikipedia/en/1/11/Stardew_Valley_cover.jpg', 97, '$14.99', true),
('hollow-knight', 'Hollow Knight', 'A haunting, hand-drawn adventure through the ruins of a forgotten kingdom.', 'Explore twisting caverns, ancient cities, and deadly wastes in this atmospheric Metroidvania. Battle tainted creatures, befriend bizarre bugs, and uncover the ancient mystery at the heart of Hallownest. With beautiful hand-drawn art and challenging, precise combat, Hollow Knight is a modern classic.', 'Team Cherry', 'Team Cherry', '2017-02-24', ARRAY['Action','Adventure','Indie'], ARRAY['Metroidvania','Difficult','Hand-drawn','Atmospheric','Exploration'], ARRAY['Single-player','Controller Support','Cloud Saves','Achievements'], 'https://upload.wikimedia.org/wikipedia/en/0/04/Hollow_Knight_first_cover_art.jpg', 'https://upload.wikimedia.org/wikipedia/en/0/04/Hollow_Knight_first_cover_art.jpg', 91, '$14.99', true),
('forza-horizon-5', 'Forza Horizon 5', 'Your epic Horizon adventure in the vibrant evolving open world of Mexico.', 'Explore the diverse landscapes of Mexico in the ultimate open-world racing adventure. Drive hundreds of world-class cars through living deserts, jungles, and historic cities, with stunning graphics, endless events, and a joyful celebration of speed and cars.', 'Playground Games', 'Xbox Game Studios', '2021-11-05', ARRAY['Racing','Sports','Action'], ARRAY['Open World','Multiplayer','Driving','Beautiful','Fast-Paced'], ARRAY['Single-player','Online PvP','Online Co-op','Controller Support','Cloud Saves','Achievements'], 'https://upload.wikimedia.org/wikipedia/en/9/9b/Forza_Horizon_5_cover_art.jpg', 'https://upload.wikimedia.org/wikipedia/en/9/9b/Forza_Horizon_5_cover_art.jpg', 92, '$59.99', true),
('resident-evil-4-remake', 'Resident Evil 4 (2023)', 'Survival is just the beginning in this reimagining of a survival horror classic.', 'Special agent Leon S. Kennedy is sent to rescue the U.S. President''s daughter from a sinister cult in rural Spain. This ground-up remake of the legendary survival horror game blends tense combat, resource management, and modernized storytelling into a relentless, heart-pounding experience.', 'Capcom', 'Capcom', '2023-03-24', ARRAY['Action','Horror','Shooter'], ARRAY['Survival Horror','Remake','Third-Person','Story Rich','Single-player'], ARRAY['Single-player','Controller Support','Cloud Saves','Achievements'], 'https://upload.wikimedia.org/wikipedia/en/8/89/Resident_Evil_4_%282023%29_cover_art.png', 'https://upload.wikimedia.org/wikipedia/en/8/89/Resident_Evil_4_%282023%29_cover_art.png', 93, '$39.99', true),
('hades', 'Hades', 'Defy the god of the dead in this award-winning rogue-like dungeon crawler.', 'Battle out of the Greek underworld as the immortal prince of the Underworld, wielding the powers of Olympus in a story-rich, endlessly replayable escape attempt. Every death brings you closer to victory in this critically-acclaimed blend of fast action and rich narrative.', 'Supergiant Games', 'Supergiant Games', '2020-09-17', ARRAY['Action','Roguelite','Indie'], ARRAY['Roguelike','Dungeon Crawler','Mythology','Story Rich','Fast-Paced'], ARRAY['Single-player','Controller Support','Cloud Saves','Achievements'], 'https://upload.wikimedia.org/wikipedia/en/7/74/Hades_video_game_cover.jpg', 'https://upload.wikimedia.org/wikipedia/en/7/74/Hades_video_game_cover.jpg', 93, '$24.99', false),
('it-takes-two', 'It Takes Two', 'A mind-bending co-op adventure built entirely around two-player play.', 'Play as the clashing couple Cody and May, turned into dolls and trapped in a fantastical world. Forced to work together through wildly varied gameplay and creative challenges, this pure co-op adventure requires two players and delivers an unforgettable ride about teamwork and love.', 'Hazelight Studios', 'Electronic Arts', '2021-03-26', ARRAY['Action','Adventure','Platformer'], ARRAY['Co-op','Puzzle','Creative','Split-screen','Story Rich'], ARRAY['Online Co-op','Local Co-op','Split-screen','Controller Support','Achievements'], 'https://upload.wikimedia.org/wikipedia/en/e/e6/It_Takes_Two_cover_art.png', 'https://upload.wikimedia.org/wikipedia/en/e/e6/It_Takes_Two_cover_art.png', 89, '$39.99', false),
('counter-strike-2', 'Counter-Strike 2', 'The world''s premier competitive FPS, rebuilt on a new engine.', 'Counter-Strike 2 is the largest technical leap in Counter-Strike history, with new volumetric smoke, upgraded maps, and reworked lighting. The definitive tactical shooter where precision, teamwork, and a thriving competitive scene make every round count.', 'Valve', 'Valve', '2023-09-27', ARRAY['Shooter','Action','Free to Play'], ARRAY['FPS','Competitive','Multiplayer','PvP','Team-Based'], ARRAY['Online PvP','Cross-Platform Play','Leaderboards','Voice Chat'], 'https://upload.wikimedia.org/wikipedia/en/b/b2/Counter-Strike_2_cover.jpg', 'https://upload.wikimedia.org/wikipedia/en/b/b2/Counter-Strike_2_cover.jpg', 83, 'Free', false);
